+fn verify_qe_identity_signature(
+    qe_identity: &[u8],
+    signature: &[u8],
+    issuer_chain: &[u8],
+) -> Result<(), VerificationError> {
+    use p256::ecdsa::{signature::Verifier, Signature, VerifyingKey};
+    use x509_parser::prelude::*;
+
+    let (_, mut certificates) = X509Certificate::from_pem(issuer_chain)
+        .map_err(|_| VerificationError::InvalidCollateral)?;
+    let leaf = certificates
+        .next()
+        .ok_or(VerificationError::InvalidCollateral)?
+        .map_err(|_| VerificationError::InvalidCollateral)?;
+
+    // Authenticate the leaf certificate with the rest of the issuer chain.
+    // `verify_certificate_chain` also checks the pinned Intel SGX root.
+    verify_certificate_chain(issuer_chain)?;
+
+    let public_key = leaf
+        .public_key()
+        .parsed()
+        .map_err(|_| VerificationError::InvalidCollateral)?;
+    let public_key = VerifyingKey::from_sec1_bytes(public_key.subject_public_key.data)
+        .map_err(|_| VerificationError::InvalidCollateral)?;
+    let signature =
+        Signature::from_der(signature).map_err(|_| VerificationError::InvalidCollateral)?;
+
+    public_key
+        .verify(qe_identity, &signature)
+        .map_err(|_| VerificationError::InvalidCollateral)
+}
+
+fn verify_qe_report_policy(
+    qe_report: &ReportBody,
+    qe_identity: &QeIdentity,
+) -> Result<(), VerificationError> {
+    let miscselect = u32::from_le_bytes(qe_report.misc_select);
+    let attributes = qe_report.attributes;
+    let mrsigner = qe_report.mr_signer;
+
+    if (miscselect & qe_identity.miscselect_mask) !=
+        (qe_identity.miscselect & qe_identity.miscselect_mask)
+        || (attributes & qe_identity.attributes_mask) !=
+            (qe_identity.attributes & qe_identity.attributes_mask)
+        || mrsigner != qe_identity.mrsigner
+        || qe_report.isv_prod_id != qe_identity.isvprodid
+    {
+        return Err(VerificationError::InvalidQeReport);
+    }
+
+    let required_isvsvn = qe_identity
+        .tcb_levels
+        .iter()
+        .filter(|level| qe_report.isv_svn >= level.isvsvn)
+        .map(|level| level.isvsvn)
+        .max()
+        .ok_or(VerificationError::InvalidQeReport)?;
+
+    if qe_report.isv_svn < required_isvsvn {
+        return Err(VerificationError::InvalidQeReport);
+    }
+
+    Ok(())
+}
